/**
 * A segmented month-and-year field with no popup (`design/components/month-input.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/month-input.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createMemo, createUniqueId, mergeProps, onCleanup, onMount, type JSX } from 'solid-js'

import {
  Each,
  agentMember,
  agentMonth,
  claimSlot,
  createCell,
  createDerived,
  elementRef,
  eraseSegment,
  fieldSegments,
  itemOf,
  monthDraft,
  monthFieldValue,
  monthOutOfBounds,
  segmentValueText,
  stepSegment,
  typeIntoSegment,
  watchEffect,
  type Defaults,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/controls/month-input.module.css'

export interface MonthInputMessages {
  empty: string
}

export interface MonthInputProps {
  'aria-describedby'?: string
  /**
   * Wired by FormField; set directly only when there is no visible label.
   */
  'aria-label'?: string
  'aria-labelledby'?: string
  'aria-required'?: boolean
  defaultValue?: string | null
  disabled?: boolean
  id?: string
  invalid?: boolean
  /**
   * Sets the segment order, the separator and the month's name.
   */
  locale?: string
  /**
   * The last month the field accepts, as `YYYY-MM`. A later month marks the field invalid.
   */
  max?: string
  /**
   * Defaults to generic English. Localized hosts pass strings from their catalog.
   */
  messages?: MonthInputMessages
  /**
   * The first month the field accepts, as `YYYY-MM`. An earlier month marks the field invalid.
   */
  min?: string
  /**
   * Serializes the month as `YYYY-MM`, as `<input type="month">` does.
   */
  name?: string
  /**
   * Called with `YYYY-MM` once both segments are filled, and with `null` once one is erased.
   */
  onChange?: (value: string | null) => void
  /**
   * Keeps segments focusable, but arrows and digits do not edit.
   */
  readOnly?: boolean
  size?: 'sm' | 'md' | 'lg'
  /**
   * A month as `YYYY-MM`, the form `<input type="month">` reports, or `null` while a segment is
   * empty. Text that is not a month shows as empty.
   */
  value?: string | null
}

/** A segmented month-and-year field with no popup. */
export default function MonthInput(given: MonthInputProps): JSX.Element {
  const props = mergeProps(
    { size: 'md', disabled: false, readOnly: false, invalid: false } as Defaults<
      MonthInputProps,
      'size' | 'disabled' | 'readOnly' | 'invalid'
    >,
    claimSlot(given, 'group'),
  )
  const uid = createUniqueId()
  const field = elementRef<HTMLElement>()
  const browserLanguage = createCell(undefined as string | undefined)
  const draft = createCell(monthDraft(props.value !== undefined ? props.value : props.defaultValue))
  const typed = createCell('')
  const reported = createCell(
    monthFieldValue(monthDraft(props.value !== undefined ? props.value : props.defaultValue)) ?? '',
  )
  const say = createDerived(() => props.messages ?? { empty: 'Empty' })
  const language = createDerived(() => props.locale ?? browserLanguage.value ?? 'en-US')
  const fieldOptions = createDerived(() => ({
    locale: language.value,
    parts: ['year', 'month'] as const,
  }))
  const segments = createDerived(() => fieldSegments(draft.value, fieldOptions.value))
  const current = createDerived(() => monthFieldValue(draft.value))
  const fieldInvalid = createDerived(
    () => props.invalid || monthOutOfBounds(current.value, { min: props.min, max: props.max }),
  )
  const commit = createDerived(() => (next: ReturnType<typeof monthDraft>): void => {
    draft.value = next
    const after = monthFieldValue(next)
    if ((after ?? '') !== reported.value) {
      reported.value = after ?? ''
      props.onChange?.(after)
    }
  })
  const segmentName = createDerived(() => (type: string): string => {
    try {
      return new Intl.DisplayNames(language.value, { type: 'dateTimeField' }).of(type) ?? type
    } catch {
      return type
    }
  })
  const moveSegment = createDerived(() => (from: EventTarget | null, step: number): void => {
    if (!(from instanceof HTMLElement)) return
    const all = [
      ...(from.closest('[role="group"]')?.querySelectorAll<HTMLElement>('[data-segment]') ?? []),
    ]
    all[all.indexOf(from) + step]?.focus()
  })
  const segmentKeys = createDerived(
    () =>
      (event: KeyboardEvent, segment: ReturnType<typeof fieldSegments>[number]): void => {
        if (segment.type === 'literal') return
        if (event.key === 'ArrowLeft' || event.key === 'ArrowRight') {
          event.preventDefault()
          typed.value = ''
          moveSegment.value(
            event.currentTarget,
            (event.key === 'ArrowRight') ===
              (getComputedStyle(event.currentTarget as HTMLElement).direction !== 'rtl')
              ? 1
              : -1,
          )
          return
        }
        if (event.ctrlKey || event.metaKey || event.key === 'Tab') return
        const editable = !props.disabled && !props.readOnly
        if (event.key === 'ArrowUp' || event.key === 'ArrowDown') {
          event.preventDefault()
          typed.value = ''
          if (editable)
            commit.value(
              stepSegment(
                draft.value,
                segment.type,
                event.key === 'ArrowUp' ? 1 : -1,
                fieldOptions.value,
              ),
            )
          return
        }
        if (event.key === 'Backspace' || event.key === 'Delete') {
          event.preventDefault()
          typed.value = ''
          if (!editable) return
          if (draft.value[segment.type] === undefined) moveSegment.value(event.currentTarget, -1)
          else commit.value(eraseSegment(draft.value, segment.type, fieldOptions.value))
          return
        }
        if (event.key.length !== 1) return
        event.preventDefault()
        if (editable)
          ((key: string): void => {
            const next = typeIntoSegment(
              draft.value,
              segment.type,
              typed.value,
              key,
              fieldOptions.value,
            )
            typed.value = next.typed
            commit.value(next.draft)
            if (next.advance) moveSegment.value(event.currentTarget, 1)
          })(event.key)
      },
  )
  const segmentInput = createDerived(
    () =>
      (event: Event, segment: ReturnType<typeof fieldSegments>[number]): void => {
        event.preventDefault()
        if (segment.type === 'literal' || !(!props.disabled && !props.readOnly)) return
        const data = (event as InputEvent).data ?? ''
        for (const key of data) {
          const next = typeIntoSegment(
            draft.value,
            segment.type,
            typed.value,
            key,
            fieldOptions.value,
          )
          typed.value = next.typed
          commit.value(next.draft)
          if (next.advance) {
            moveSegment.value(event.currentTarget, 1)
            break
          }
        }
      },
  )
  const effect1 = () => {
    browserLanguage.value = globalThis.navigator?.language
  }
  onMount(effect1)
  const effect2 = () => {
    void (
      props.value !== undefined &&
      (props.value !== null || current.value !== null) &&
      ((draft.value = monthDraft(props.value)),
      (reported.value = monthFieldValue(monthDraft(props.value)) ?? ''))
    )
  }
  watchEffect(
    createMemo(() => props.value),
    effect2,
    false,
  )
  let release3: (() => void) | undefined
  const effect3 = () => {
    release3?.()
    const ran = agentMember({
      member: 'MonthInput',
      element: () => field.value,
      state: () => ({
        value: current.value ?? '',
        disabled: props.disabled,
        invalid: fieldInvalid.value,
        readonly: props.readOnly,
      }),
      actions: {
        set: {
          argument: 'text',
          run: (value) =>
            (() => {
              if (props.readOnly) throw new Error('The field is read-only.')
              commit.value(monthDraft(agentMonth(value, { min: props.min, max: props.max })))
            })(),
        },
        clear: () =>
          (() => {
            if (props.readOnly) throw new Error('The field is read-only.')
            commit.value({})
          })(),
      },
    })
    release3 = () => {
      ran()
    }
  }
  onMount(effect3)
  onCleanup(() => release3?.())
  return (
    <div
      class={styles.field}
      role="group"
      id={props.id}
      aria-label={props['aria-label']}
      aria-labelledby={props['aria-labelledby']}
      aria-describedby={props['aria-describedby']}
      aria-disabled={props.disabled ? 'true' : undefined}
      data-size={props.size}
      data-disabled={props.disabled ? '' : undefined}
      data-invalid={fieldInvalid.value ? '' : undefined}
      data-readonly={props.readOnly ? '' : undefined}
      data-member="month-input"
      ref={field.attach}
    >
      {/* segments */}
      <div class={styles.segments}>
        <Each of={segments.value} by={(segment, at) => `month-${segment.type}-${at}`} renew>
          {(segment) => (
            <>
              {segment.type === 'literal' ? (
                <span class={styles.separator} aria-hidden="true">
                  {segment.text}
                </span>
              ) : (
                <div
                  class={styles.segment}
                  role="spinbutton"
                  id={`${uid}-month-${segment.type}`}
                  aria-label={segmentName.value(segment.type)}
                  aria-labelledby={
                    props['aria-labelledby']
                      ? `${props['aria-labelledby']} ${uid}-month-${segment.type}`
                      : undefined
                  }
                  aria-describedby={props['aria-describedby']}
                  aria-valuenow={segment.placeholder ? undefined : segment.value}
                  aria-valuemin={segment.min}
                  aria-valuemax={segment.max}
                  aria-valuetext={segmentValueText(segment, language.value, say.value.empty)}
                  aria-required={props['aria-required'] ? 'true' : undefined}
                  aria-readonly={props.readOnly ? 'true' : undefined}
                  aria-disabled={props.disabled ? 'true' : undefined}
                  aria-invalid={fieldInvalid.value ? 'true' : undefined}
                  contenteditable={!props.disabled && !props.readOnly ? 'true' : undefined}
                  inputmode={segment.type === 'dayPeriod' ? undefined : 'numeric'}
                  spellcheck="false"
                  tabindex={props.disabled ? undefined : '0'}
                  data-segment={segment.type}
                  data-placeholder={segment.placeholder ? '' : undefined}
                  data-disabled={props.disabled ? '' : undefined}
                  onfocus={() => (typed.value = '')}
                  onkeydown={($event: KeyboardEvent) => segmentKeys.value($event, itemOf(segment))}
                  onbeforeinput={($event: InputEvent) =>
                    segmentInput.value($event, itemOf(segment))
                  }
                >
                  {segment.text}
                </div>
              )}
            </>
          )}
        </Each>
      </div>
      {props.name !== undefined ? (
        <input
          type="hidden"
          name={props.name}
          value={current.value ?? ''}
          disabled={props.disabled ? true : undefined}
        />
      ) : null}
    </div>
  )
}

MonthInput.controlKind = 'group'
